/** Audio bundled by Metro: the import is the asset id `expo-audio` takes. */
declare module '*.mp3' {
  const asset: number;
  export default asset;
}

/** Images bundled by Metro: the import is the asset id `Image` takes. */
declare module '*.png' {
  const asset: number;
  export default asset;
}

declare module '*.webp' {
  const asset: number;
  export default asset;
}
